import{_ as i,c as a,a2 as e,o as t}from"./chunks/framework.CoXjB5sU.js";const c=JSON.parse('{"title":"Configure email service","description":"","frontmatter":{"prev":{"text":"Update platform","link":"/doc/faqs/admin/update-current-distribution"},"next":{"text":"Set upload limits","link":"/doc/faqs/admin/setup-upload-limits"}},"headers":[],"relativePath":"doc/faqs/admin/configure-email.md","filePath":"doc/faqs/admin/configure-email.md"}'),n={name:"doc/faqs/admin/configure-email.md"};function l(r,s,h,p,o,d){return t(),a("div",null,s[0]||(s[0]=[e(`<h1 id="configure-email-service" tabindex="-1">Configure email service <a class="header-anchor" href="#configure-email-service" aria-label="Permalink to &quot;Configure email service&quot;">​</a></h1><p>ioChem-BD sends emails to its users: the link to set the password of a new account, the <em>Forgot your password?</em> link of the login page, and publication and review notifications. All of them go through the Browse module, so the mail server is configured there.</p><p>The installer sets the mail parameters (see <a href="./../../guides/installation/required-steps.html#mail-settings">Mail settings</a>). Follow this page to check the connection to the mail server or to change its configuration later.</p><h2 id="initial-checks" tabindex="-1">Initial checks <a class="header-anchor" href="#initial-checks" aria-label="Permalink to &quot;Initial checks&quot;">​</a></h2><p>You need the name or IP of the mail server, its port and the protocol it uses. The most common ones are:</p><ul><li>25: plain communication, no encryption</li><li>465: SSL</li><li>587: STARTTLS</li></ul><p>Ports and protocols may differ: check them with your IT team.</p><p>From the ioChem-BD server, check that the port is reachable (change the server name and the port to match yours):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smtp.university.edu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 587</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ncat:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Connected</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XXX.XXX.XXX.XXX:587.</span></span></code></pre></div><p>A timeout or a <em>connection refused</em> message means that a firewall is blocking the connection: the port must be opened on the network side.</p><p>To check the protocol, open a session with <em>openssl</em>. For STARTTLS servers add <code>-starttls smtp</code>; for SSL servers (port 465) leave it out:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smtp.university.edu:587</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -starttls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smtp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -brief</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CONNECTION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ESTABLISHED</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TLSv1.3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The mail parameters are in <em>BASE_PATH/browse/config/local.cfg</em>, <em>BASE_PATH</em> being the installation folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SMTP mail server, port and account (username and password only if the server requires them)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smtp.university.edu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.server.port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 587</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.server.username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd@university.edu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.server.password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XXXXXXX</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Sender of every email</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.from.address</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd@university.edu</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Site administrator and feedback recipient</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd-admin@university.edu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feedback.recipient</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd-admin@university.edu</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Encryption: SSL (usually port 465) or STARTTLS (usually port 587)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mail.extraproperties</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.smtp.ssl.enable=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.smtp.starttls.enable=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Set the encryption in <em>mail.extraproperties</em>:</p><table tabindex="0"><thead><tr><th>Server</th><th>Port</th><th>mail.extraproperties</th></tr></thead><tbody><tr><td>Plain, no encryption</td><td>25</td><td><code>mail.smtp.ssl.enable=false, mail.smtp.starttls.enable=false</code></td></tr><tr><td>SSL</td><td>465</td><td><code>mail.smtp.ssl.enable=true, mail.smtp.starttls.enable=false</code></td></tr><tr><td>STARTTLS</td><td>587</td><td><code>mail.smtp.ssl.enable=false, mail.smtp.starttls.enable=true</code></td></tr></tbody></table><p>Other <a href="https://jakarta.ee/specifications/mail/2.1/apidocs/jakarta.mail/jakarta/mail/package-summary.html" target="_blank" rel="noreferrer">Jakarta Mail SMTP properties</a> can be appended to <em>mail.extraproperties</em>, separated by commas. For example, if the server needs a specific protocol version, add <code>mail.smtp.ssl.protocols=TLSv1.2</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Restart Tomcat after changing the mail parameters: <code>BASE_PATH/bin/iochembd.sh restart tomcat</code>.</p></div><h2 id="test-the-configuration" tabindex="-1">Test the configuration <a class="header-anchor" href="#test-the-configuration" aria-label="Permalink to &quot;Test the configuration&quot;">​</a></h2><p>Send a test email to the administrator address (<em>mail.admin</em>) from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/browse/bin/dspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-email</span></span></code></pre></div><p>The command prints the mail settings and whether the message was sent. If it fails, the error explains why (wrong credentials, unreachable server, protocol mismatch).</p><p>Please contact us at <a href="mailto:contact@iochem-bd.org" target="_blank" rel="noreferrer">contact@iochem-bd.org</a> if you need help configuring the mail service.</p>`,24)]))}const m=i(n,[["render",l]]);export{c as __pageData,m as default};
